//! Cargo-driven `netkvm.sys` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DriverEntry@8", 0x10000u64),
        "x86_64" => ("x86_64-pc-windows-gnu", "DriverEntry", 0x10000u64),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DriverEntry", 0x7ffb00000000u64),
        o => panic!("netkvm-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:c:virtio", "import:ndis", "import:ntoskrnl", "import:hal", "engine:c:memcmp"],
        "x86_64" => &["engine:c:virtio", "import:ndis", "import:ntoskrnl", "import:hal", "engine:c:memcmp"],
        "aarch64" => &["engine:c:virtio", "import:ndis", "import:ntoskrnl", "import:hal", "engine:c:memcmp"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/drivers/network/dd/netkvm",
        "vendor/netkvm",
        "vendor/netkvm/Common",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/virtio",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["NDIS51_MINIPORT", "NDIS_MINIPORT_DRIVER", "WINVER=0x502", "_WIN32_WINNT=0x502"];

    Linker::new(target_json)
        .c_from_compile_db("netkvm_shims", &["vendor/netkvm/Common/ParaNdis-Common.c", "vendor/netkvm/Common/ParaNdis-Oid.c", "vendor/netkvm/Common/ParaNdis-VirtIO.c", "vendor/netkvm/Common/ParaNdis-Debug.c", "vendor/netkvm/Common/sw-offload.c", "vendor/netkvm/wxp/ParaNdis5-Driver.c", "vendor/netkvm/wxp/ParaNdis5-Impl.c", "vendor/netkvm/wxp/ParaNdis5-Oid.c"])
        .rc("vendor/netkvm/wxp/parandis.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("drivers/network/ndis/ndis.spec", "ndis.sys", "ndis")
        .import_lib("ntoskrnl/ntoskrnl.spec", "ntoskrnl.exe", "ntoskrnl")
        .import_lib("hal/hal.spec", "hal.dll", "hal")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        // cmake's kernel-mode links keep every section.
        .keep_all_sections()
        .link(ModuleKind::KernelDll {
            entry: entry.into(),
            image_base,
        });
}
